const input = $input.first().json;
return [{ json: { ...input, prompt: `Analizá este mensaje comercial.
Canal: ${input.channel}
Remitente: ${input.sender_id}
Mensaje: ${input.text}

Determiná intención, temperatura (frio/tibio/caliente), etapa comercial, producto de interés, información faltante, próxima acción y respuesta sugerida. No inventes información.` } }];
